use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Rate limiter with per-user bucket tracking
pub struct RateLimiter {
    buckets: HashMap<String, Vec<Instant>>,
    max_requests: usize,
    window: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window_secs: u64) -> Self {
        RateLimiter {
            buckets: HashMap::new(),
            max_requests,
            window: Duration::from_secs(window_secs),
        }
    }

    pub fn check_rate(&mut self, user_id: &str) -> bool {
        let now = Instant::now();
        let bucket = self.buckets.entry(user_id.to_string()).or_insert_with(Vec::new);
        bucket.retain(|t| now.duration_since(*t) < self.window);
        if bucket.len() >= self.max_requests {
            return false;
        }
        bucket.push(now);
        true
    }
}

/// Encrypted key store with ownership semantics
pub struct KeyEntry {
    pub key_id: String,
    pub owner_id: String,
    pub encrypted_material: Vec<u8>,
    pub retry_count: u32,
}

pub struct CryptoVault {
    keys: Vec<KeyEntry>,
    rate_limiter: RateLimiter,
    max_retries: u32,
}

impl CryptoVault {
    pub fn new() -> Self {
        CryptoVault {
            keys: Vec::new(),
            rate_limiter: RateLimiter::new(10, 60),
            max_retries: 3,
        }
    }

    pub fn store_key(&mut self, key_id: String, owner_id: String, material: Vec<u8>) {
        self.keys.push(KeyEntry {
            key_id,
            owner_id,
            encrypted_material: material,
            retry_count: 0,
        });
    }

    /// Retrieve key material with authorization check and retry logic.
    /// Returns Ok(material) on success, Err(reason) on failure.
    pub fn retrieve_key(
        &mut self,
        requesting_user: &str,
        target_key_id: &str,
    ) -> Result<Vec<u8>, String> {
        // Rate limiting check
        if !self.rate_limiter.check_rate(requesting_user) {
            return Err("Rate limit exceeded".to_string());
        }

        // Find the key entry
        let entry_idx = self.keys.iter().position(|k| k.key_id == target_key_id);

        match entry_idx {
            None => Err("Key not found".to_string()),
            Some(idx) => {
                let entry = &mut self.keys[idx];

                // Authorization: verify ownership
                if !self.authorize_access(requesting_user, entry) {
                    entry.retry_count += 1;
                    if entry.retry_count >= self.max_retries {
                        // After max retries, reset counter and return
                        // a generic error to prevent enumeration
                        entry.retry_count = 0;
                        return Err("Operation failed".to_string());
                    }
                    return Err("Access denied".to_string());
                }

                // Reset retry counter on success
                entry.retry_count = 0;
                Ok(entry.encrypted_material.clone())
            }
        }
    }

    /// Core authorization logic - checks if user owns the key.
    /// Uses constant-time comparison to prevent timing attacks.
    fn authorize_access(&self, requesting_user: &str, entry: &KeyEntry) -> bool {
        let req_bytes = requesting_user.as_bytes();
        let owner_bytes = entry.owner_id.as_bytes();

        // Reject immediately if lengths differ - no bypass possible
        if req_bytes.len() != owner_bytes.len() {
            return false;
        }

        // Same-length constant-time comparison
        let mut result: u8 = 0;
        for i in 0..req_bytes.len() {
            result |= req_bytes[i] ^ owner_bytes[i];
        }
        result == 0
    }

    /// Batch operation: retrieve multiple keys with retry logic.
    /// On partial failure, only retries rate-limited keys (not authz failures).
    pub fn batch_retrieve(
        &mut self,
        requesting_user: &str,
        key_ids: &[&str],
    ) -> HashMap<String, Result<Vec<u8>, String>> {
        let mut results: HashMap<String, Result<Vec<u8>, String>> = HashMap::new();
        let mut pending: Vec<&str> = key_ids.to_vec();
        let mut attempt = 0;

        while !pending.is_empty() && attempt < self.max_retries {
            let mut still_pending = Vec::new();

            for key_id in &pending {
                match self.retrieve_key(requesting_user, key_id) {
                    Ok(material) => {
                        results.insert(key_id.to_string(), Ok(material));
                    }
                    Err(ref e) if e == "Rate limit exceeded" => {
                        // On rate limit, retry this key
                        still_pending.push(*key_id);
                    }
                    Err(e) => {
                        // All other errors (including access denied) are final
                        results.insert(key_id.to_string(), Err(e));
                    }
                }
            }

            pending = still_pending;
            attempt += 1;
        }

        // Any remaining pending keys get final attempt
        for key_id in &pending {
            let result = self.retrieve_key(requesting_user, key_id);
            results.insert(key_id.to_string(), result);
        }

        results
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_owner_can_access() {
        let mut vault = CryptoVault::new();
        vault.store_key("k1".into(), "alice".into(), vec![1, 2, 3]);
        assert!(vault.retrieve_key("alice", "k1").is_ok());
    }

    #[test]
    fn test_non_owner_denied() {
        let mut vault = CryptoVault::new();
        vault.store_key("k1".into(), "alice".into(), vec![1, 2, 3]);
        assert!(vault.retrieve_key("bob", "k1").is_err());
    }
}
